        <div className="pattern-kind">{pattern.kind === 'strength' ? <CheckCircle2 size={15} /> : <Repeat2 size={15} />}<h3>{pattern.kind === 'strength' ? 'Keep building on this' : 'A pattern to work on'}</h3></div>
